sources.DefineSprite_2210_任务系统/frame_1/DoAction:
var maxTaskNum = 10;
var nowTaskType = "mainTask";
var role = _parent.map.role;
var nowTask;
var friend;
mainButton.nowState = true;
this.open = function()
{
   this.showTask(this.nowTaskType);
   this.openPanel();
};
this.showTask = function(taskType)
{
   if(taskType != undefined)
   {
      this.nowTaskType = taskType;
   }
   this.detail.text = "";
   this.drawButton._visible = false;
   var _loc2_;
   var _loc3_;
   _loc2_ = 0;
   while(_loc2_ < this.maxTaskNum)
   {
      this["taskTitle" + _loc2_].close();
      _loc2_ = _loc2_ + 1;
   }
   _loc2_ = 0;
   _loc3_ = 0;
   while(_loc2_ < this[taskType].length && _loc3_ < this.maxTaskNum)
   {
      if(this[taskType][_loc2_].isDoing == true)
      {
         this["taskTitle" + _loc3_].open(this[taskType][_loc2_]);
         _loc3_ = _loc3_ + 1;
      }
      _loc2_ = _loc2_ + 1;
   }
};
this.taskDetail = function(task)
{
   if(task == undefined || task.isDoing == false)
   {
      return false;
   }
   this.nowTask = task;
   this.detail.text = task.explain;
   this.detail.text += "\r\r进度:";
   var _loc2_;
   _loc2_ = task.need.length;
   while(_loc2_)
   {
      this.detail.text += "\n" + task.need[_loc2_ - 1].name + ":" + task.need[_loc2_ - 1].number + "/" + task.need[_loc2_ - 1].needNumber;
      _loc2_ = _loc2_ - 1;
   }
   if(task.isComplete)
   {
      this.drawButton._visible = true;
   }
   else
   {
      this.drawButton._visible = false;
   }
};
this.getMainTaskName = function()
{
   var _loc2_ = "";
   var _loc1_;
   _loc1_ = 0;
   while(_loc1_ < mainTask.length)
   {
      if(mainTask[_loc1_].isComplete == false)
      {
         mainTask[_loc1_].isDoing = true;
         _loc2_ = mainTask[_loc1_].name;
         break;
      }
      _loc1_ = _loc1_ + 1;
   }
   return _loc2_;
};
this.nextMainTask = function()
{
   if(mainTask[0].isComplete == false && mainTask[1].isComplete == false)
   {
      if(_parent.map.role.vocational == "战士")
      {
         mainTask[0].isDoing = true;
      }
      else
      {
         mainTask[1].isDoing = true;
      }
      showTask(nowTaskType);
      return true;
   }
   if(mainTask[2].isComplete == false && mainTask[3].isComplete == false)
   {
      if(_parent.map.role.vocational == "战士")
      {
         mainTask[2].isDoing = true;
      }
      else
      {
         mainTask[3].isDoing = true;
      }
      showTask(nowTaskType);
      return true;
   }
   if(mainTask[4].isComplete == false && mainTask[5].isComplete == false)
   {
      if(_parent.map.role.vocational == "战士")
      {
         mainTask[4].isDoing = true;
      }
      else
      {
         mainTask[5].isDoing = true;
      }
      showTask(nowTaskType);
      return true;
   }
   var _loc3_;
   _loc3_ = 6;
   var _loc4_;
   while(_loc3_ < mainTask.length)
   {
      if(mainTask[_loc3_].isComplete == false)
      {
         _loc4_ = mainTask[_loc3_].name;
         if(_loc4_.substr(0,4) == "魔军主将")
         {
            _root.魔军主将转世 += 1;
         }
         mainTask[_loc3_].isDoing = true;
         showTask(nowTaskType);
         return true;
      }
      _loc3_ = _loc3_ + 1;
   }
   return false;
};
this.setDailyTask = function(taskName, monstName1, monstName2)
{
   var _loc1_;
   _loc1_ = dailyTask.length - 1;
   while(_loc1_ >= 0)
   {
      if(dailyTask[_loc1_].name == taskName)
      {
         switch(taskName)
         {
            case "初级军功":
            case "中级军功":
            case "高级军功":
               dailyTask[_loc1_].need = [{name:monstName1,number:0,needNumber:6},{name:monstName2,number:0,needNumber:6}];
               break;
            case "初级功勋":
            case "中级功勋":
            case "高级功勋":
               dailyTask[_loc1_].need = [{name:monstName1,number:0,needNumber:4},{name:monstName2,number:0,needNumber:4}];
               break;
            case "初级悬赏":
            case "中级悬赏":
            case "高级悬赏":
               dailyTask[_loc1_].need = [{name:monstName1,number:0,needNumber:1}];
               break;
            default:
               return false;
         }
         dailyTask[_loc1_].isDoing = true;
         showTask(nowTaskType);
         return true;
      }
      _loc1_ = _loc1_ - 1;
   }
   return false;
};
this.setHonorTask = function(todo)
{
   var _loc2_;
   _loc2_ = getTask("荣誉任务");
   if(todo == false)
   {
      _loc2_.isDoing = false;
      showTask(nowTaskType);
      return true;
   }
   if(_loc2_.isDoing != true)
   {
      _loc2_.isDoing = true;
      _loc2_.isComplete = false;
      _loc2_.need = [{name:"怪物",number:0,needNumber:100}];
      showTask(nowTaskType);
      _global.sysMsg.addMsg("接受日常任务 荣誉任务");
      return true;
   }
   return false;
};
this.setFriendTask = function(taskNpc)
{
   var _loc3_;
   _loc3_ = dailyTask.length - 1;
   var _loc4_;
   while(_loc3_ >= 0)
   {
      if(dailyTask[_loc3_].name == "好友委托")
      {
         if(dailyTask[_loc3_].isDoing == true)
         {
            return false;
         }
         friend = taskNpc;
         taskNpc.isTask = true;
         switch(random(4))
         {
            case 0:
               dailyTask[_loc3_].explain = "名称：收集灵魂晶石\r要求：收集1个灵魂晶石\r奖励：魔石、奇异兽\r说明：收集1个灵魂晶石给" + friend.nTitle + friend.name + "。";
               dailyTask[_loc3_].need = [{name:"灵魂晶石",number:0,needNumber:1}];
               break;
            case 1:
               dailyTask[_loc3_].explain = "名称：收集幻魔晶石\r要求：收集2个幻魔晶石\r奖励：魔石、奇异兽\r说明：收集2个幻魔晶石给" + friend.nTitle + friend.name + "。";
               dailyTask[_loc3_].need = [{name:"幻魔晶石",number:0,needNumber:2}];
               break;
            case 2:
               dailyTask[_loc3_].explain = "名称：收集魔魂晶石\r要求：收集3个魔魂晶石\r奖励：魔石、奇异兽\r说明：收集3个魔魂晶石给" + friend.nTitle + friend.name + "。";
               dailyTask[_loc3_].need = [{name:"魔魂晶石",number:0,needNumber:3}];
               break;
            case 3:
               _loc4_ = "龙怪";
               switch(_parent.map.homeCity)
               {
                  case "卡萨诺城二":
                     _loc4_ = "鹿角兽";
                     break;
                  case "树心城":
                     _loc4_ = "骑士亡魂";
                     break;
                  case "戈壁":
                     _loc4_ = "巨猿";
                     break;
                  case "沼泽":
                     _loc4_ = "招魂使";
                     break;
                  case "南城":
                     _loc4_ = "恐兽";
                     break;
                  case "边关":
                     _loc4_ = "提风";
                     break;
                  case "冰宫":
                     _loc4_ = "暗黑弥塞亚";
               }
               dailyTask[_loc3_].explain = "名称：去杀怪\r要求：消灭怪物。\r奖励：魔石、奇异兽\r说明：消灭进度显示的怪物，朋友越多奖励超高。";
               dailyTask[_loc3_].need = [{name:_loc4_,number:0,needNumber:4},{name:_loc4_ + "精英",number:0,needNumber:2}];
         }
         dailyTask[_loc3_].isDoing = true;
         showTask(nowTaskType);
         _global.sysMsg.addMsg("接受日常任务 好友委托");
         return true;
      }
      _loc3_ = _loc3_ - 1;
   }
   return false;
};
this.getTask = function(taskName)
{
   var _loc2_;
   var _loc1_;
   _loc2_ = 0;
   while(_loc2_ < allTask.length)
   {
      _loc1_ = 0;
      while(_loc1_ < allTask[_loc2_].length)
      {
         if(allTask[_loc2_][_loc1_].name == taskName)
         {
            return allTask[_loc2_][_loc1_];
         }
         _loc1_ = _loc1_ + 1;
      }
      _loc2_ = _loc2_ + 1;
   }
   return false;
};
this.catchThing = function(thing, num)
{
   var _loc9_;
   var _loc6_;
   if(thing.type != undefined)
   {
      _loc6_ = !(thing.number == undefined || thing.number == 0) ? thing.number : 1;
      if(thing.name == undefined)
      {
         _loc9_ = thing.type;
      }
      else
      {
         _loc9_ = thing.name;
      }
   }
   else
   {
      _loc9_ = thing;
      _loc6_ = num;
   }
   if(isNaN(_loc6_))
   {
      return false;
   }
   var _loc4_;
   var _loc3_;
   var _loc5_;
   _loc4_ = allTask.length;
   var _loc7_;
   while(_loc4_)
   {
      _loc3_ = allTask[_loc4_ - 1].length;
      while(_loc3_)
      {
         _loc5_ = allTask[_loc4_ - 1][_loc3_ - 1].need.length;
         while(_loc5_)
         {
            if(allTask[_loc4_ - 1][_loc3_ - 1].isDoing == true && allTask[_loc4_ - 1][_loc3_ - 1].need[_loc5_ - 1].number < allTask[_loc4_ - 1][_loc3_ - 1].need[_loc5_ - 1].needNumber && allTask[_loc4_ - 1][_loc3_ - 1].need[_loc5_ - 1].name == _loc9_ && allTask[_loc4_ - 1][_loc3_ - 1].levels <= _parent.map.role.levels)
            {
               _loc7_ = allTask[_loc4_ - 1][_loc3_ - 1].need[_loc5_ - 1].needNumber - allTask[_loc4_ - 1][_loc3_ - 1].need[_loc5_ - 1].number;
               if(_loc6_ > _loc7_)
               {
                  allTask[_loc4_ - 1][_loc3_ - 1].need[_loc5_ - 1].number += _loc7_;
                  _loc6_ -= _loc7_;
               }
               else
               {
                  allTask[_loc4_ - 1][_loc3_ - 1].need[_loc5_ - 1].number += _loc6_;
                  _loc6_ = 0;
               }
               if(!(thing.number == undefined || thing.number == 0))
               {
                  thing.number = _loc6_;
               }
               if(taskComplete(allTask[_loc4_ - 1][_loc3_ - 1]))
               {
                  _global.sysMsg.addMsg(allTask[_loc4_ - 1][_loc3_ - 1].type + " " + allTask[_loc4_ - 1][_loc3_ - 1].name + "任务完成");
                  if(allTask[_loc4_ - 1][_loc3_ - 1].type == "主线任务")
                  {
                     nextMainTask();
                  }
               }
               showTask(nowTaskType);
               taskDetail(nowTask);
               return true;
            }
            _loc5_ = _loc5_ - 1;
         }
         _loc3_ = _loc3_ - 1;
      }
      _loc4_ = _loc4_ - 1;
   }
};
this.taskComplete = function(task)
{
   var _loc1_;
   task.isComplete = true;
   _loc1_ = task.need.length;
   while(_loc1_)
   {
      if(task.need[_loc1_ - 1].number < task.need[_loc1_ - 1].needNumber)
      {
         task.isComplete = false;
         break;
      }
      _loc1_ = _loc1_ - 1;
   }
   return task.isComplete;
};
this.mainButton.onPress = function()
{
   this._parent.flashBtn(this);
   this._parent.showTask("mainTask");
};
this.branchButton.onPress = function()
{
   this._parent.flashBtn(this);
   this._parent.showTask("branchTask");
};
this.dareButton.onPress = function()
{
   this._parent.flashBtn(this);
   this._parent.showTask("dareTask");
};
this.dailyButton.onPress = function()
{
   this._parent.flashBtn(this);
   this._parent.showTask("dailyTask");
};
this.flashBtn = function(btn)
{
   this.mainButton.nowState = false;
   this.branchButton.nowState = false;
   this.dareButton.nowState = false;
   this.dailyButton.nowState = false;
   btn.nowState = true;
   nowTask = undefined;
};
this.flashTitleColor = function()
{
   var _loc2_;
   _loc2_ = 0;
   while(_loc2_ < this.maxTaskNum)
   {
      this["taskTitle" + _loc2_].flashTextColor();
      _loc2_ = _loc2_ + 1;
   }
};
this.delButton.onRelease = function()
{
   if(nowTask == undefined)
   {
      return false;
   }
   _global.msg.open("\r\r\r确定删除" + nowTask.name + "任务吗?",this._parent.deleteTask);
};
this.deleteTask = function()
{
   if(nowTask == undefined)
   {
      return false;
   }
   if(nowTask.type == "主线任务")
   {
      _global.msg.open("\r\r非常抱歉\r作者不允许删除主线任务");
      return false;
   }
   if(nowTask.name == "军衔")
   {
      _global.msg.open("\r\r注意\r不要随便删除任务");
      return false;
   }
   var _loc3_;
   _loc3_ = 0;
   while(_loc3_ < nowTask.need.length)
   {
      nowTask.need[_loc3_].number = 0;
      _loc3_ = _loc3_ + 1;
   }
   if(nowTask.name == "好友委托")
   {
      friend.isTask = false;
   }
   if(nowTask.name == "荣誉任务")
   {
      _parent.map.role.xxx_credit -= 1;
      _global.sysMsg.addMsg("声望减少一点");
   }
   nowTask.isComplete = false;
   nowTask.isDoing = false;
   nowTask = undefined;
   showTask(nowTaskType);
   return true;
};
this.drawButton.onRelease = function()
{
   this._parent.getPrize();
};
this.getPrize = function()
{
   if(nowTask == undefined || nowTask.isComplete == false || nowTask.isDoing == false)
   {
      return false;
   }
   if(nowTask.name == "荣誉任务")
   {
      _global.msg.open("\r\r\r请到国王那里领取奖励。");
      return false;
   }
   var _loc6_;
   if(nowTask.name == "好友委托")
   {
      friend.isTask = false;
      _loc6_ = _parent.friend.getAllLevels();
      nowTask.prize[0] = {type:"魔石",val:_loc6_ * 10 + 100};
      switch(Math.floor(_loc6_ / 7))
      {
         case 0:
            nowTask.prize[1] = {type:"奇异兽"};
            break;
         case 1:
            nowTask.prize[1] = {type:"6星奇异兽"};
            break;
         case 2:
            nowTask.prize[1] = {type:"8星奇异兽"};
            break;
         case 3:
            nowTask.prize[1] = {type:"12星奇异兽"};
            break;
         case 4:
            nowTask.prize[1] = {type:"15星奇异兽"};
            break;
         case 5:
            nowTask.prize[1] = {type:"19星奇异兽"};
            break;
         case 6:
         default:
            nowTask.prize[1] = {type:"23星奇异兽"};
      }
      _global.sysMsg.addMsg("获得 " + nowTask.prize[1].type);
   }
   var _loc5_;
   _loc5_ = nowTask.prize.length;
   var _loc4_;
   while(_loc5_)
   {
      switch(nowTask.prize[_loc5_ - 1].type)
      {
         case "魔石":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "魔石");
            this._parent.map.role.xxx_ms += nowTask.prize[_loc5_ - 1].val;
            break;
         case "资源":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "资源");
            this._parent.map.role.xxx_res += nowTask.prize[_loc5_ - 1].val;
            break;
         case "军功":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "军功");
            this._parent.map.role.militaryExploitUp(nowTask.prize[_loc5_ - 1].val);
            break;
         case "功勋":
            _global.sysMsg.addMsg("获得 " + _global.numberToString(nowTask.prize[_loc5_ - 1].val) + "功勋");
            this._parent.map.role.exploitUp(nowTask.prize[_loc5_ - 1].val);
            break;
         case "声望":
            this._parent.map.role.creditUp(nowTask.prize[_loc5_ - 1].val);
            break;
         case "出征3个幻兽":
            _global.sysMsg.addMsg("!!! " + role.myName + "竟然掌握同时出征3个幻兽的能力，恭喜");
            this._parent.huanShou.maxBattleNum = 3;
            break;
         case "接荣誉任务":
            _global.msg.open("\r\r\r接受国王委托任务 荣誉任务",this.setHonorTask,true);
            break;
         default:
            if(nowTask.prize[_loc5_ - 1].type == "武器" || nowTask.prize[_loc5_ - 1].type == "衣服" || nowTask.prize[_loc5_ - 1].type == "头盔" || nowTask.prize[_loc5_ - 1].type == "鞋" || nowTask.prize[_loc5_ - 1].type == "幸运符" || nowTask.prize[_loc5_ - 1].type == "庇护铃铛" || nowTask.prize[_loc5_ - 1].type == "翡翠铃铛" || nowTask.prize[_loc5_ - 1].type == "凤翼铃铛")
            {
               _parent.upDataWeapon(nowTask.prize[_loc5_ - 1]);
               _parent.backPack.setThing(nowTask.prize[_loc5_ - 1]);
               break;
            }
            if(nowTask.prize[_loc5_ - 1].number > 0)
            {
               _loc4_ = 0;
               while(_loc4_ < nowTask.prize[_loc5_ - 1].number)
               {
                  _parent.createThing(nowTask.prize[_loc5_ - 1]);
                  _loc4_ = _loc4_ + 1;
               }
               break;
            }
            _parent.createThing(nowTask.prize[_loc5_ - 1]);
      }
      _loc5_ = _loc5_ - 1;
   }
   if(nowTask.type == "日常任务")
   {
      _loc5_ = 0;
      while(_loc5_ < nowTask.need.length)
      {
         nowTask.need[_loc5_].number = 0;
         _loc5_ = _loc5_ + 1;
      }
      nowTask.isComplete = false;
   }
   nowTask.isDoing = false;
   nowTask = undefined;
   showTask(this.nowTaskType);
};

sources.DefineSprite_2210_任务系统/frame_1/DoAction_:
var mainTask = new Array();
var branchTask = new Array();
var dareTask = new Array();
var dailyTask = new Array();
var allTask = new Array(dailyTask,mainTask,branchTask,dareTask);
this.initData = function()
{
   mainTask.push({type:"主线任务",name:"新手训练一",explain:"名称：新手训练一\r要求：1级以上，消灭6个鹿角兽\r奖励：武器、衣服、100魔石\r说明：鹿角兽在卡萨诺城野外，经过西边(就是你的左边)传送点后就可以看到它们。\r传送提示：站在传送点上按Q键或者用鼠标点击就可以传进下一下地图",isComplete:false,isDoing:false,levels:1,need:[{name:"鹿角兽",number:0,needNumber:6}],prize:[{type:"武器",grade:1,name:"长军刀",mhdj:0,vocational:"战士",levels:1,minAttack:2,maxAttack:18},{type:"衣服",grade:1,name:"锁环甲",mhdj:0,vocational:"战士",levels:1,defense:3},{type:"魔石",val:100}]});
   mainTask.push({type:"主线任务",name:"新手训练一",explain:"名称：新手训练一\r要求：1级以上，消灭6个鹿角兽\r奖励：武器、衣服、100魔石\r说明：鹿角兽在卡萨诺城野外，经过西边(就是你的左边)传送点后就可以看到它们。\r传送提示：站在传送点上按Q键或者用鼠标点击就可以传进下一下地图",isComplete:false,isDoing:false,levels:1,need:[{name:"鹿角兽",number:0,needNumber:6}],prize:[{type:"武器",grade:1,name:"蛇杖",mhdj:0,vocational:"法师",levels:1,minAttack:9,maxAttack:14},{type:"衣服",grade:1,name:"旅者装",mhdj:0,vocational:"法师",levels:1,defense:2},{type:"魔石",val:100}]});
