this.onRollOver = function()
{
   this.闪光.gotoAndPlay(1);
   if(this._alpha != 0)
   {
      this.传送点提示.info.text = "按Q进入\r" + this.toMap;
      this.传送点提示._visible = true;
   }
};
this.onRollOut = function()
{
   this.闪光.gotoAndStop(1);
   this.传送点提示._visible = false;
};
this.onPress = function()
{
   this._parent.catchMouseDown = true;
};
this.onRelease = function(direct)
{
   if(direct == true || this.hitTest(this._parent.role._x,this._parent.role._y,false) == true && this._parent.role.life > 0)
   {
      this._parent.jumpToMap(this);
   }
};
this.闪光.stop();
this.传送点提示._visible = false;
if(this._alpha == 0)
{
   this.useHandCursor = false;
}

