   myTitle = npc.nTitle;
   if(npc.jobLevels > 0)
   {
      npcName.text = npc.jobLevels + "级";
   }
   else
   {
      npcName.text = "";
   }
   npcName.text += myTitle + " " + myName;
   nameBack._width = 135 * npcName.text.length / 10;
   nameBack._x = -70 + (135 - nameBack._width) / 2;
