this.dropItem = function(mName, fX, fY, level)
{
   if(level == undefined)
   {
      level = this.role.levels;
   }
   switch(mName)
   {
      case "普通怪":
         if(random(10000) < 500)
         {
            this.dropNormalItem(fX,fY,level);
         }
         this.dropStone(fX,fY,level);
         this.dropFlower(fX,fY,level);
         this.dropHSItem(fX,fY,level);
         if(random(10000) < 2000)
         {
            this.dropMsBag(fX,fY,level);
         }
         if(random(10000) < 50)
         {
            this._parent.createThing({type:"幸运之门"},true,fX,fY);
         }
         return;
      case "精英怪":
         if(random(10000) < 500)
         {
            this.dropNormalItem(fX,fY,level);
         }
         this.dropStone(fX,fY,level);
         if(random(10000) < 7500)
         {
            this.dropMsBag(fX,fY,level);
         }
         return;
      case "头目":
         if(random(10000) > 5000)
         {
            this.dropBossItem(fX,fY,level);
         }
