class MonsterMC extends SecreteCodeMC
{
   var _isAlive;
   var _parent;
   var _visible;
   var _x;
   var _y;
   var attackFire;
   var attackHeight;
   var attackLength;
   var attackStopTime;
   var attackType;
   var attackTypeNum;
   var damage;
   var defense;
   var faceTo;
   var frostMC;
   var getSecreteCode;
   var gotoAndStop;
   var guardHeight;
   var guardLength;
   var heavyDamageMC;
   var hpBar;
   var jook;
   var levels;
   var maxAttack;
   var maxLife;
   var minAttack;
   var motion;
   var myName;
   var myTarget;
   var nonDefenseMC;
   var playAction;
   var reduceDamage;
   var setSecreteCode;
   var skillEffect;
   var speedX;
   var speedY;
   var stopRate;
   var stopTime;
   var type;
   var 不要作弊888;
   var expRate = 3;
   var baseExp = 15;
   function MonsterMC()
   {
      super();
   }
   function set life(val)
   {
      if(isNaN(val))
      {
         return;
      }
      this.不要作弊888 = this.setSecreteCode(val);
      if(this.life > this.maxLife)
      {
         this.不要作弊888 = this.setSecreteCode(this.maxLife);
      }
      else if(this.life < 0)
      {
         this.不要作弊888 = this.setSecreteCode(0);
      }
      this.changeHpMp();
   }
   function get life()
   {
      return this.getSecreteCode(this.不要作弊888);
   }
   function set isAlive(val)
   {
      this._isAlive = val;
      if(true == this._isAlive)
      {
         if(this.attackType != undefined)
         {
            this.gotoAndStop("敌对幻兽");
            this.playAction.幻兽种类.gotoAndStop(this.type);
            this.hpBar._y = -5 - this.playAction.幻兽种类._height;
         }
         else
         {
            this.gotoAndStop(this.type);
            this.hpBar._y = -5 - this.playAction._height;
         }
         this.hpBar._y = -5 - this.playAction.幻兽种类._height;
         this._visible = true;
         this.myTarget = undefined;
      }
      else
      {
         this._visible = false;
      }
      this.motion = "站立";
      this.frostMC.stopRun();
      this.nonDefenseMC.stopRun();
      this.heavyDamageMC.stopRun();
   }
   function get isAlive()
   {
      return this._isAlive;
   }
   function 站立()
   {
      switch(this.faceTo)
      {
         case "左":
            this.playAction.gotoAndStop("左");
            break;
         case "右":
            this.playAction.gotoAndStop("右");
      }
      this.motion = "站立";
      return true;
   }
   function 向左跑()
   {
      if("向左跑" != this.motion)
      {
         this.playAction.gotoAndStop("向左跑");
         this.motion = "向左跑";
      }
      this._x -= this.speedX;
      return true;
   }
   function 向右跑()
   {
      if("向右跑" != this.motion)
      {
         this.playAction.gotoAndStop("向右跑");
         this.motion = "向右跑";
      }
      this._x += this.speedX;
      return true;
   }
   function 向上跑()
   {
      if("左" == this.faceTo && "向左跑" != this.motion)
      {
         this.playAction.gotoAndStop("向左跑");
      }
      else if("右" == this.faceTo && "向右跑" != this.motion)
      {
         this.playAction.gotoAndStop("向右跑");
      }
      this.motion = "向上跑";
      this._y -= this.speedY;
      this.changeDepth();
      return true;
   }
   function 向下跑()
   {
      if("左" == this.faceTo && "向左跑" != this.motion)
      {
         this.playAction.gotoAndStop("向左跑");
      }
      else if("右" == this.faceTo && "向右跑" != this.motion)
      {
         this.playAction.gotoAndStop("向右跑");
      }
      this.motion = "向下跑";
      this._y += this.speedY;
      this.changeDepth();
      return true;
   }
   function changeDepth()
   {
      this._parent.newDepth = true;
      return true;
   }
   function Activities()
   {
      if(!this.isAlive || "使用技能中" == this.motion)
      {
         return false;
      }
      var _loc4_;
      if("使用技能结束" == this.motion)
      {
         switch(this.skillEffect)
         {
            case "攻击":
            case "技能":
            case "远程攻击":
               if(Math.abs(this._x - this.myTarget._x) <= this.attackLength && Math.abs(this._y - this.myTarget._y) <= this.attackHeight)
               {
                  _loc4_ = this.minAttack + random(this.maxAttack - this.minAttack + 1);
                  this.myTarget.byAttack(this,this,_loc4_,_loc4_ == this.maxAttack);
               }
         }
         this.skillEffect = "无";
         this.stopTime = this.attackStopTime;
         this.站立();
         return true;
      }
      if(this.stopTime > 0)
      {
         this.stopTime = this.stopTime - 1;
         return false;
      }
      if(random(this.stopRate * 10) < 15)
      {
         this.stopTime = this.attackStopTime;
         this.站立();
         return false;
      }
      if(!this.myTarget.isAlive)
      {
         this.myTarget = undefined;
      }
      if(undefined == this.myTarget)
      {
         this.lockTarget();
      }
      var _loc2_;
      var _loc3_;
      if(undefined != this.myTarget && this.myTarget.isAlive)
      {
         _loc2_ = this._x - this.myTarget._x;
         _loc3_ = this._y - this.myTarget._y;
         this.faceTo = _loc2_ <= 0 ? "右" : "左";
         if(_loc2_ > Math.abs(this.attackLength * 2))
         {
            this.lockTarget();
         }
         else if(_loc3_ > Math.abs(this.attackHeight * 2))
         {
            this.lockTarget();
         }
         if(_loc2_ > this.attackLength * 0.8)
         {
            this.向左跑();
         }
         else if(_loc2_ < (- this.attackLength) * 0.8)
         {
            this.向右跑();
         }
         if(_loc3_ > this.attackHeight * 0.8)
         {
            this.向上跑();
         }
         else if(_loc3_ < (- this.attackHeight) * 0.8)
         {
            this.向下跑();
         }
         if(Math.abs(_loc2_) <= this.attackLength && Math.abs(_loc3_) <= this.attackHeight)
         {
            if(this.attackType != undefined)
            {
