      this._y = _ymouse - 16;
   }
   startDrag(this,0);
   this._xclick = _xmouse;
   this._yclick = _ymouse;
   this._visible = true;
   if(this.isDoubleClick())
   {
      this.MovingDoubleClick();
      return true;
   }
   this.clickInterval = getTimer();
   if(Key.isDown(17))
   {
      if(this._parent.map.goods.throwGoods(this._parent.map.role._x,this._parent.map.role._y,this) == true)
      {
