         this._visible = false;
      }
      return true;
   }
   if(Key.isDown(16))
   {
      if(_root.map.nowDangerous == false)
      {
         if(_root.shop.setThing(this) == true)
         {
            stopDrag();
            this._visible = false;
         }
      }
      return true;
   }
   return true;
