this.huanShou.battle = function(hs)
{
   var _loc3_;
   if(hs.battle == false)
   {
      if(this.nowBattleNum < this.maxBattleNum)
      {
         hs.battle = true;
         this.nowBattleNum = this.nowBattleNum + 1;
         _loc3_ = 1;
         while(_loc3_ <= this.maxBattleNum)
         {
            if(this._parent["battleHuanShouPanel" + _loc3_].isOpen == false)
            {
               this._parent["battleHuanShouPanel" + _loc3_].open(hs);
               _global.sysMsg.addMsg("出征 " + hs.type + "幻兽，战斗力增加" + this._parent["battleHuanShouPanel" + _loc3_].attackFire);
               _global.playSound("出征幻兽.wav");
               break;
            }
            _loc3_ = _loc3_ + 1;
         }
      }
   }
   else
   {
      this.nowBattleNum = this.nowBattleNum - 1;
      if(hs.inOne)
      {
         this.inOne(hs);
      }
      hs.battle = false;
      _loc3_ = 1;
      while(_loc3_ <= this.maxBattleNum)
      {
         if(this._parent["battleHuanShouPanel" + _loc3_].huanShou == hs)
         {
            this._parent["battleHuanShouPanel" + _loc3_].close();
            _global.sysMsg.addMsg("召回 " + hs.type + "幻兽");
            _global.playSound("召回幻兽.wav");
            break;
         }
         _loc3_ = _loc3_ + 1;
      }
   }
   this.sortHuanShou();
   return hs.battle;
};
