this.makeBell.setThing = function(target)
{
   if(target.type == "凤翼铃铛" || target.type == "翡翠铃铛" || target.type == "庇护铃铛")
   {
      if(this.item1.hitTest(_xmouse,_ymouse,false) == true)
      {
         if(this.item1.type != "空格")
         {
            this._parent.backPack.setThing(this.item1);
         }
         this.item1.setThing(target);
      }
      else if(this.item2.hitTest(_xmouse,_ymouse,false) == true)
      {
         if(this.item2.type != "空格")
         {
            this._parent.backPack.setThing(this.item2);
         }
         this.item2.setThing(target);
      }
      else if(this.item1.type == "空格")
      {
         this.item1.setThing(target);
      }
      else
      {
         if(this.item2.type != "空格")
         {
            return false;
         }
         this.item2.setThing(target);
      }
      this.flashInfo();
      return true;
   }
   return false;
};
