      this.pt1.text = this.item1.pure;
   }
   else
   {
      this.pt1.text = "";
   }
   if(this.item2.type != "空格")
   {
      this.pt2.text = this.item2.pure;
   }
   else
   {
      this.pt2.text = "";
   }
   if(this.item1.type == "空格" || this.item2.type == "空格")
   {
      this.info.text = " 这里可以加工铃铛,两件品质相同的铃铛可以合成一件品质更加高的铃铛。";
