         {
            this.mover.stopMove(false);
         }
         else
         {
            this.closeAllPanel();
         }
         break;
      case 32:
         if(this.relive._visible == true)
         {
            this.relive.onPress();
         }
         this.map.goods.autoPickUp(this.map.role._x,this.map.role._y);
         break;
      case 17:
      case 81:
         this.map.jumpMap();
         break;
      case 49:
         clearInterval(intervalID_1);
